import type { CollectionConfig } from "payload";
import path from "path";
import { fileURLToPath } from "url";

const dirname = path.dirname(fileURLToPath(import.meta.url));

/**
 * Media library — image/file uploads stored on the server's disk (a persistent
 * Docker volume in production). `alt` is required so every image ships with SEO
 * alt text. Responsive sizes are generated by sharp for fast, right-sized
 * delivery.
 */
export const Media: CollectionConfig = {
  slug: "media",
  admin: { group: "Content" },
  access: {
    read: () => true, // public — images are served on the website
    create: ({ req: { user } }) => Boolean(user),
    update: ({ req: { user } }) => Boolean(user),
    delete: ({ req: { user } }) => Boolean(user),
  },
  upload: {
    // Absolute path on disk; overridable via env for the production volume.
    staticDir: process.env.PAYLOAD_MEDIA_DIR || path.resolve(dirname, "../../media"),
    // Disallow arbitrary or executable SVG uploads to prevent Stored XSS.
    // Allow safe images, documents (PDF), and hero video formats (MP4, WebM, MOV).
    mimeTypes: [
      "image/jpeg",
      "image/png",
      "image/webp",
      "image/avif",
      "application/pdf",
      "video/mp4",
      "video/webm",
      "video/quicktime",
    ],
    imageSizes: [
      { name: "thumbnail", width: 400, height: undefined, position: "centre" },
      { name: "card", width: 768, height: undefined },
      { name: "feature", width: 1280, height: undefined },
      { name: "hero", width: 1920, height: undefined },
    ],
    focalPoint: true,
  },
  hooks: {
    beforeValidate: [
      ({ req, operation }) => {
        if ((operation === "create" || operation === "update") && req.file) {
          const isVideo = req.file.mimetype?.startsWith("video/");
          const maxBytes = isVideo ? 50 * 1024 * 1024 : 10 * 1024 * 1024; // 50MB for videos, 10MB for images/docs
          if (req.file.size > maxBytes) {
            throw new Error(
              `File size exceeds maximum allowed limit of ${isVideo ? "50MB" : "10MB"}.`,
            );
          }
        }
      },
    ],
  },
  fields: [
    {
      name: "alt",
      type: "text",
      required: true,
      admin: { description: "Describe the image for SEO and accessibility (required)." },
    },
    {
      name: "caption",
      type: "text",
      admin: { description: "Optional caption shown under the image where used." },
    },
  ],
};
